UPDATE "Stock"
SET "quantity"  = "quantity" - #{qty},
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "warehouseId" = #{warehouseId}
  AND "itemId" = #{itemId}
  AND "batchId" = #{batchId}
  AND "locationId" = #{locationId}
  AND "quantity" >= #{qty}
  AND "quantity" - "preAllocatedQty" >= #{qty}

mapper.select:
UPDATE "Stock"
SET "quantity"  = "quantity" - #{qty},
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "warehouseId" = #{warehouseId}
  AND "itemId" = #{itemId}
  AND "batchId" = #{batchId}
  AND "locationId" = #{locationId}
  AND "quantity" >= #{qty}
  AND "quantity" - "preAllocatedQty" >= #{qty}
RETURNING "quantity"

mapper.update:
UPDATE "Stock"
SET "quantity"  = "quantity" + #{qty},
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "warehouseId" = #{warehouseId}
  AND "itemId" = #{itemId}
  AND "batchId" = #{batchId}
  AND "locationId" = #{locationId}

mapper.select:
SELECT "id", "warehouseId", "itemId", "batchId", "locationId", "quantity",
       "preAllocatedQty", "updatedAt"
FROM "Stock"
WHERE "warehouseId" = #{warehouseId}
  AND "itemId" = #{itemId}
  AND "locationId" = #{locationId}
  AND "batchId" <> 0
  AND "quantity" > 0
  AND "quantity" - "preAllocatedQty" > 0
ORDER BY "id" ASC

SELECT "batchId" AS "batchId", MAX("createdAt") AS "maxCreatedAt"
FROM "StockTransaction"
WHERE "warehouseId" = #{warehouseId}
  AND "itemId" = #{itemId}
  AND "bizCode" = 'inbound'
  AND "batchId" IN

    #{bid}

GROUP BY "batchId"
